//! Engine adapter: the ordinary IBP source rows of a family, generated by RustRed exactly as `rr_node` does for its
//! certificates (`node::driver`: `compile_family` of the PRESENTED family text, then
//! `SourceSystem::<N>::from_family_with_capacity(&family, true)`, rows in `SourceSystem::rows()` order), written in
//! the certificate's `source_row` line format (same `m`, `differentiated_loop`, `contraction_momentum` convention and
//! the same integral / coefficient printing as `node::driver::write_cert_header`). The proof kernels parse these lines
//! with the same affine-row parser they use for stored rows and compare both.
use rustred::family::IntegralFamily;
use rustred::node::driver::compile_family;
use rustred::solver::SourceSystem;

fn q(s: &str) -> String {
    crate::core::jstr(s)
}

fn lines<const N: usize>(fam: &IntegralFamily) -> Result<Vec<Vec<u8>>, String> {
    let sources = SourceSystem::<N>::from_family_with_capacity(fam, true).map_err(|e| format!("source system: {e:?}"))?;
    let (loops, externals) = (fam.loop_count(), fam.external_count());
    let contraction: Vec<usize> = (loops..loops + externals).rev().chain(0..loops).collect();
    let mut out = vec![];
    for (m, row) in sources.rows().iter().enumerate() {
        let (loop_id, momentum) = (m / contraction.len(), contraction[m % contraction.len()]);
        let terms: Vec<String> = row.iter().map(|t| format!("[{},{}]", q(&t.integral.to_string()), q(&t.coefficient.to_string()))).collect();
        out.push(format!("{{\"type\":\"source_row\",\"m\":{m},\"differentiated_loop\":{loop_id},\"contraction_momentum\":{momentum},\"terms\":[{}]}}", terms.join(",")).into_bytes());
    }
    Ok(out)
}

/// Source rows of the presented family text (as stored in a table header's `family_source` / `F.family.sym`).
pub fn source_row_lines(family_text: &str) -> Result<Vec<Vec<u8>>, String> {
    let fam = compile_family(family_text)?;
    match fam.denominator_count() {
        5 => lines::<5>(&fam),
        9 => lines::<9>(&fam),
        12 => lines::<12>(&fam),
        14 => lines::<14>(&fam),
        20 => lines::<20>(&fam),
        n => Err(format!("arity {n}: compiled for 5, 9, 12, 14, 20 (as rr_node)")),
    }
}
